// Each chapter's question bank is its own lazily-loaded chunk (dynamic import), so the
// app only downloads the chapters you actually open. Chapter question COUNTS (used by the
// home screens) live in ./counts.js, which is generated by `npm run gen:counts` — it runs
// automatically before `npm run dev` and `npm run build`.
//
// Question schema:
// { id, type, question, options[], correctIndex, explanation, difficulty }
//
// To add a chapter: create banks/<file>.js exporting the array, then add a line to LOADERS.

import { QUESTION_COUNTS } from './counts';

export const LOADERS = {
  'some-basics-chemistry': () => import('./banks/someBasicsOfChemistry').then(m => m.SOME_BASICS_CHEMISTRY),
  'structure-atom': () => import('./banks/structureOfAtom').then(m => m.STRUCTURE_ATOM),
  'solutions': () => import('./banks/solutions').then(m => m.SOLUTIONS),
  'electrochemistry': () => import('./banks/electrochemistry').then(m => m.ELECTROCHEMISTRY),
  'chemical-kinetics': () => import('./banks/chemicalKinetics').then(m => m.CHEMICAL_KINETICS),
  'chemical-bonding-molecular-structure': () => import('./banks/molecularstructure').then(m => m.MOLECULAR_STRUCTURE),
  'thermodynamics': () => import('./banks/thermodynamics').then(m => m.THERMODYNAMICS),
  'equilibrium': () => import('./banks/equilibrium').then(m => m.EQUILIBRIUM),
  'redox-reactions': () => import('./banks/redoxreactions').then(m => m.REDOX_REACTIONS),
  'organic-chem-basic-principles-techniques': () => import('./banks/organicChemBasicsPrinciplesTechniques').then(m => m.ORGANIC_CHEM_PRINCIPLES_TECHNIQUES),
  'periodic-table': () => import('./banks/periodictable').then(m => m.ELEMENTS_PERIODIC_PROPERTIES),
  'hydrocarbons': () => import('./banks/hydrocarbons').then(m => m.HYDROCARBONS),
  'd-f-elements': () => import('./banks/DandFblockElements').then(m => m.D_F_BLOCK_ELEMENTS),
  'coordination-compounds': () => import('./banks/coordinationCompounds').then(m => m.COORDINATION_COMPOUNDS),
  'haloalkanes-haloarenes': () => import('./banks/haloalkanesHaloarenes').then(m => m.HALOALKANES_HALOARENES),
  'alcohols-phenols-ethers': () => import('./banks/alcoholsPhenolsEthers').then(m => m.ALCOHOLS_PHENOLS_ETHERS),
  'aldehydes-ketones-carboxylicacids': () => import('./banks/aldehydesketonescarboxylicacids').then(m => m.ALDEHYDES_KETONES_CARBOXYLICACIDES),
  'amines': () => import('./banks/amines').then(m => m.AMINES),
  'biomolecules': () => import('./banks/biomolecules').then(m => m.BIOMOLECULES),
};

const cache = {};

// Resolves to the chapter's question array ([] if the chapter has no bank).
export function getChapterQuestions(chapterId) {
  const load = LOADERS[chapterId];
  if (!load) return Promise.resolve([]);
  if (!cache[chapterId]) {
    cache[chapterId] = load().catch((err) => {
      delete cache[chapterId]; // allow a retry after a failed chunk download
      throw err;
    });
  }
  return cache[chapterId];
}

// Synchronous count for chapter cards / "chapters live" — no bank is downloaded.
export function getChapterQuestionCount(chapterId) {
  return QUESTION_COUNTS[chapterId] || 0;
}
